        ["zhipuai/glm-5.1"] = new(false, 131072, 200000, false),
        ["zhipuai/glm-5.2"] = new(false, 131072, 1000000, false),
        ["zhipuai/glm-5.3"] = new(false, 131072, 1000000, false),
